"""Native E1/G1 author profiles and exact unchanged A/M binding retention."""
from pathlib import Path
from datetime import datetime, timezone
import json
import hashlib
import copy

D=Path(__file__).resolve().parent
ROOT=D.parents[6]
OLD=D.parent/'biologie-ecology20-current391-author-v2'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(name,value):
    p=D/name;p.parent.mkdir(parents=True,exist_ok=True)
    with p.open('x')as f:f.write(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
materials=read(D/'materials/twenty-whole-goals-forty-complete-DEEN-cases.author.json')['goals']
plans=read(D/'neutral-twenty-current-whole-imageplans.author.json')['goals']
ids=[m['goalId']for m in materials]
# Each transfer understanding states a concrete boundary exercised in the whole second case.
understandings=[
 ('concept','Mikrobielle Gemeinschaften stehen in bedingten nützlichen/neutralen/schädlichen Wechselbeziehungen zum Menschen.','Microbial communities interact with humans beneficially, neutrally or harmfully under specific conditions.','Gesunde Gemeinschaft bedeutet weder vollständige Sterilität noch universelle Wirkung eines einzelnen Produkts.','Healthy communities mean neither complete sterility nor universal benefit from one product.','Hautbarriere/Gewebeeintritt gegenüber Darmstoffwechsel/Gemeinschaftsstörung.','Skin barrier/tissue entry versus gut metabolism/community disruption.'),
 ('concept','Bakterien vermehren sich als Zellen, Viren wirtsabhängig; Vermehrung und Abwehr erklären mögliche Verläufe.','Bacteria reproduce as cells and viruses depend on hosts; replication and defence explain possible courses.','Übertragungsweg und Wirkziel begrenzen Prävention und Therapie; Antibiotikum, Impfung und Hygiene sind nicht austauschbar.','Transmission route and target limit prevention/treatment; antibiotics, vaccination and hygiene are not interchangeable.','Zell-/Virus-Vermehrungsmodell gegenüber Wasser-/Atemübertragung und Schutzvergleich.','Cell/virus replication versus water/respiratory transmission and prevention comparison.'),
 ('concept','Unspezifische Barrieren/frühe Abwehr und spezifische humorale/zellvermittelte Antwort haben verschiedene Aufgaben.','Nonspecific barriers/early defence and specific humoral/cell-mediated responses perform distinct roles.','Spezifisches Gedächtnis unterstützt Sekundärantwort, während Allergie eine Fehlreaktion auf harmlose Antigene ist.','Specific memory supports secondary responses while allergy is a malfunction towards harmless antigens.','Hautbakterien/Pollen gegenüber Atemvirus/Milben und Wiederholungsantwort.','Skin bacteria/pollen versus respiratory virus/mites and repeat responses.'),
 ('concept','Aktive Immunisierung baut eigene Antwort/Gedächtnis auf; passive liefert zeitweilige fertige Antikörper.','Active immunization builds personal responses/memory; passive supplies temporary ready-made antibodies.','Vorbeugende Entscheidungen brauchen Wirksamkeit, Nutzen/Risiko und Eignung; weder sofortiger Vollschutz noch lebenslanges Pauschalversprechen.','Preventive decisions need effectiveness, benefits/risks and suitability; neither instant complete protection nor blanket lifelong guarantees follow.','Präparatevergleich gegenüber Vorbereitungszeit/kurzfristigem Bedarf und Garantieprüfung.','Preparation comparison versus lead time/immediate need and guarantee critique.'),
 ('modeling','Antibiotika verändern Zielbakterien und weitere Biozönoseanteile; vorbestehende resistente Varianten können selektiert werden.','Antibiotics affect targets and other community members; pre-existing resistant variants can be selected.','Relative Resistenzzunahme beweist keine zielgerichtete Umwandlung; fehlendes virales Wirkziel begrenzt behaupteten Nutzen.','Rising relative resistance establishes no directed transformation; absence of viral targets limits claimed benefit.','Quantitative Gemeinschaftsverschiebung gegenüber viralem Ziel und unbelegter Werbung.','Quantitative community shift versus viral target and unsupported advertising.'),
 ('representation','Zuckerbausteine, Glycerin-Fettsäurereste und Aminosäuren/Peptidbindungen begründen drei Makronährstoffgruppen.','Sugar units, glycerol–fatty-acid residues and amino-acid/peptide bonds distinguish three macronutrient groups.','Unsättigung/Kettenlänge ändern keine grundlegende Stoffzuordnung, und Lebensmittel können Mischungen sein.','Unsaturation/chain length do not change fundamental group assignment and foods can be mixtures.','Stärke/Triglycerid/Protein gegenüber Disaccharid/ungesättigtem Fett/kurzem Peptid.','Starch/triglyceride/protein versus disaccharide/unsaturated fat/short peptide.'),
 ('modeling','Nährstofffunktionen und Zusammensetzung begründen bedarfsgerechte Energie-, Baustoff- und Mikronährstoffversorgung.','Nutrient roles and composition justify adequate energy, building-material and micronutrient provision.','Lebensumstände und Vorlieben ändern passende Zusammenstellung; ein Lebensmittel, Kalorienwert oder Ernährungslabel allein genügt nicht.','Circumstances/preferences affect composition; one food, calorie value or dietary label alone is insufficient.','Einseitiges/vielfältiges Angebot gegenüber unterschiedlicher Aktivität und gesicherter pflanzlicher Alternative.','One-sided/varied menus versus different activity and a nutritionally secured plant-based alternative.'),
 ('concept','Enzyme katalysieren spezifische Teilchenumsetzung durch passende Wechselwirkungen und niedrigere Aktivierungsbarriere.','Enzymes catalyse specific particle conversion through matching interactions and lower activation barriers.','Enzymverbrauch oder veränderte Nettoenergiebilanz folgt nicht aus Katalyse; starre Schlüssel-Schloss-Form ist begrenzt.','Catalysis implies neither enzyme consumption nor changed net energy; rigid lock-and-key shape is limited.','Amylase/Stärke und Energieprofil gegenüber Protease/Peptid und Fehlermodell.','Amylase/starch and energy profile versus protease/peptide and faulty model.'),
 ('data','Temperatur, pH und Substratbedingungen beeinflussen Raten; unterschiedliche menschliche Enzyme passen zu ihren Körpermilieus.','Temperature, pH and substrate affect rates; distinct human enzymes fit bodily environments.','Kälte und irreversible Hitze-Denaturierung unterscheiden sich; Sättigung und spezifische Milieus begrenzen pauschale Optima.','Cooling and irreversible heat denaturation differ; saturation and specific environments limit blanket optima.','Temperatur-/Vorbehandlungsdaten gegenüber pH-Vergleich und Substratsättigung.','Temperature/pretreatment data versus pH comparison and substrate saturation.'),
 ('concept','Transport und abgestimmte organ-/substratspezifische Enzyme zerlegen drei Nährstoffgruppen zu resorbierbaren Bestandteilen.','Transport and coordinated organ-/substrate-specific enzymes digest three nutrient groups to absorbable components.','Galle emulgiert, Lipase spaltet; Peristaltik, Verdauung und Resorption haben unterschiedliche Funktionen.','Bile emulsifies and lipase cleaves; peristalsis, digestion and absorption have distinct functions.','Vollständiger Mahlzeitenweg gegenüber falschem Universal-Magenenzym/Direktblutweg.','Complete meal pathway versus false universal stomach enzyme/direct-to-blood route.'),
 ('representation','Dünnes Epithel, Zotten/Mikrovilli und Blut-/Lymphgefäße unterstützen selektive Aufnahme und Abtransport.','Thin epithelium, villi/microvilli and blood/lymph vessels support selective uptake/removal.','Membranwege und zelluläre Verarbeitung verhindern freie Ganznahrungspassage; Fläche/Abtransport begrenzen Aufnahme.','Membrane routes and cellular processing prevent free whole-food passage; area/removal limit uptake.','Normale Zottenstruktur gegenüber geringerer Oberfläche und fehlerhaftem Durchlassmodell.','Normal villus structure versus reduced area and faulty permeability model.'),
 ('representation','Jeweilige Partialdruckgefälle bestimmen passive Nettodiffusion von O2/CO2 über große dünne Austauschflächen.','Specific partial-pressure gradients determine passive net O2/CO2 diffusion across large thin exchange surfaces.','Lungen- und Gewebeseite haben unterschiedliche Richtungen; Fläche/Strecke, Belüftung und Perfusion begrenzen Austausch.','Lung/tissue gradients have different directions; area/path length, ventilation and perfusion limit exchange.','Quantitative Lungengefälle gegenüber Gewebegefällen und geänderter Fläche/Strecke.','Quantitative lung gradients versus tissue gradients and changed area/path length.'),
 ('representation','Herzantrieb, Klappen und zwei gekoppelte Kreisläufe transportieren aufgenommene Stoffe zu Zellen und Abgabestoffe zurück.','Heart pumping, valves and linked pulmonary/systemic circuits deliver absorbed substances and return wastes.','Arterie/Vene bezeichnet Richtung zum Herzen, nicht Farbe; Aufnahme, Bluttransport und Zellstoffwechsel bleiben getrennt.','Artery/vein refers to heart-relative direction, not colour; uptake, blood transport and metabolism stay distinct.','Explizite Kammerroute mit Darm/Muskel gegenüber fehlender Lungenroute und falscher Farbetikette.','Explicit chamber route with intestine/muscle versus missing pulmonary route and false colour labels.'),
 ('modeling','Vorsorge kann Lungen-/Kreislaufrisiken mindern; medizinische Verfahren wirken an fachlich bestimmten geeigneten Ursachen/Engstellen.','Prevention can reduce lung/circulatory risks; medical procedures address professionally assessed suitable mechanisms/narrowing.','Begrenzte Behandlung ersetzt keinen umfassenden Schutz und erlaubt ohne Individualdaten keine Verordnung.','Limited treatment replaces no comprehensive prevention and permits no prescription without individual evidence.','Gefäßengstelle/Versorgung gegenüber Atemwegsweite und Präventionswerbung.','Vascular narrowing/supply versus airway calibre and prevention advertising.'),
 ('concept','Exotherme Glucoseoxidation koppelt verfügbare Energie an ATP-Synthese; ATP-Hydrolyse kann an Zellarbeit gekoppelt sein.','Exothermic glucose oxidation couples available energy to ATP synthesis; hydrolysis can be coupled to cellular work.','Stoffe/Energie verschwinden nicht; ATP ist schnell regenerierter Träger, kein langfristiges Großdepot oder reine Bindungsbruchenergie.','Matter/energy do not vanish; ATP is rapidly replenished, not a major long-term store or energy from bond breaking alone.','Muskelarbeit mit vollständiger Stoffbilanz gegenüber aktivem Transport und Vorratsfehlmodell.','Muscle work with complete matter balance versus active transport and faulty storage.'),
 ('modeling','Aerobe vollständige Oxidation und Glykolyse/Lactatbildung unterscheiden Produkte und ATP-Ausbeute pro Glucose.','Aerobic complete oxidation and glycolysis/lactate formation differ in products and ATP yield per glucose.','Beide Wege können je nach Bedarf/Versorgung beitragen; Lactatbildung verlangt nicht absolut sauerstofffreien ganzen Körper.','Both routes can contribute with demand/supply; lactate formation needs no entirely oxygen-free body.','Bedingte Modellbilanz pro Glucose gegenüber Dauer-/Kurzbelastung und Alles-oder-Nichts-Behauptung.','Conditional per-glucose model yield versus sustained/brief exertion and all-or-nothing claims.'),
 ('concept','Nahrung, Gebiss, Aufnahme und Verdauungsorgane stehen in funktionellem Zusammenhang; Symbionten helfen beim Pflanzenaufschluss.','Food, teeth, intake and digestive organs relate functionally; symbionts assist processing plants.','Gemeinsame Pflanzenkost bedeutet keine identischen Vormagen-/Hinterdarmwege oder Wiederkäuen bei jedem Säugetier.','Shared plant food implies neither identical forestomach/hindgut pathways nor universal rumination.','Hund/Rind gegenüber Pferd/Rind und verschiedener Fermentationslokalisation.','Dog/cattle versus horse/cattle and differing fermentation sites.'),
 ('concept','Knochen/Gelenke tragen und bewegen; Muskeln ziehen über Sehnen, Bänder stabilisieren Knochenverbindungen.','Bones/joints support and move; muscles pull through tendons and ligaments stabilize bone connections.','Vorsorge vermindert einseitige Beanspruchung durch passende Last und Bewegung, nicht durch eine starre perfekte Haltung für alle.','Prevention reduces one-sided strain through suitable load/activity rather than one rigid perfect posture for everyone.','Arm/Gegenspieler und langes Sitzen gegenüber Aufstehen und asymmetrischer Rucksacklast.','Arm/antagonists and prolonged sitting versus rising and asymmetric backpack load.'),
 ('concept','Ausgewogene Ernährung liefert unterschiedliche notwendige Funktionen; Verdauung schafft kleine aufnehmbare Bestandteile.','Balanced nutrition supplies distinct necessary functions; digestion creates small absorbable components.','Nahrung dient Energie und Baustoffen; unverdaute Reste werden weitertransportiert statt ganze Mahlzeiten direkt ins Blut.','Food supplies energy and building material; undigested remains continue instead of whole meals entering blood.','Vollständige Mahlzeit/Verdauungsweg gegenüber einseitigem Angebot und direktem Mund-Zell-Fehler.','Complete meal/digestive route versus one-sided menu and direct mouth–cell error.'),
 ('representation','Atemluft wird erneuert, Gase werden an dünnen Lungenflächen ausgetauscht und durch beide Kreisläufe transportiert.','Breathing renews air; gases exchange across thin lung surfaces and travel through both circuits.','Herz erzeugt O2 nicht, Ausatemluft bleibt O2-haltig und Gesundheitsschutz mindert Risiken ohne Vollgarantie.','Heart does not create O2, exhaled air retains O2 and health protection reduces risks without absolute guarantees.','Normale Luft-/Blutroute gegenüber Aktivitätsbedarf und fehlenden Lungen-/Farbpfaden.','Normal air/blood route versus activity demand and missing pulmonary/colour pathways.')
]
assert len(understandings)==20
review='biologie-human20-current391-positive-author-v1'
candidates={'schemaVersion':1,'authoringContract':'positive-understanding-evidence-candidates-v1','reviewId':review,
    'reviewedAt':datetime.now(timezone.utc).isoformat().replace('+00:00','Z'),
    'reviewer':'Codex human20 material author; GPT-6 family, exact serving revision not exposed','goals':[]}
for n,(m,p,u)in enumerate(zip(materials,plans,understandings),1):
    archetype,core_de,core_en,transfer_de,transfer_en,var_de,var_en=u
    ex=[]
    for suffix,de,en,case in [('core',core_de,core_en,m['cases'][0]),('transfer',transfer_de,transfer_en,m['cases'][1])]:
        ex.append({'id':f'human20-{n:02d}-{suffix}','essentialUnderstandingDe':de,'essentialUnderstandingEn':en,'observablePerformanceDe':case['task']['de'],'observablePerformanceEn':case['task']['en']})
    briefs=[{'id':c['id'],'taskDemandDe':c['material']['de']+' '+c['task']['de'],'taskDemandEn':c['material']['en']+' '+c['task']['en'],
             'expectedPerformanceDe':c['modelAnswer']['de'],'expectedPerformanceEn':c['modelAnswer']['en'],
             'understandingFocusDe':core_de+' '+transfer_de,'understandingFocusEn':core_en+' '+transfer_en}for c in m['cases']]
    candidates['goals'].append({'goalId':m['goalId'],'reason':'Ganzes aktuelles bilinguales SekI-Ziel mit zwei konkreten eigenen vollständigen Material-/Modellantwortfällen; tatsächliche unabhängige fachliche und Rasterreviews stehen aus.',
        'dissent':['E1/G1-Autorkandidat; keine reale Lernendenleistung, E2, menschliche Prüfung, Freigabe oder Erprobung.',p['sourceBoundary'],
                   'Eigene modellhafte Lehrfälle, keine individuellen Patientendaten, persönliche Therapie-/Dosierungsvorgaben oder Impfkalender. Tatsächliche finale Rasterbindungen stehen aus.'],
        'profile':{'archetype':archetype,'expectations':ex,'coverageExpectations':{'requiredExpectationIds':[x['id']for x in ex],
            'alternativeExpectationGroups':[], 'minimumIndependentDemonstrations':2,
            'freshVariationRequired':True,'independentTransferRequired':True},
            'variationAxes':[{'id':f'human20-{n:02d}-context-mechanism','textDe':var_de,'textEn':var_en}],
            'applicationCaseBriefs':briefs}})
write('P20.current-text-preimage.author.candidates.json',candidates)
conf=read(D.parent/'biologie-ecology20b-current391-author-v1/P20.current-text-preimage.author.config.json')
conf['reviewId']=review;conf['reviewPath']=str((D/'P20.current-text-preimage.author.review.jsonl').relative_to(ROOT))
conf['scope']={'label':'20 exact current whole source-bounded SekI human/health author profiles; no strict completion yet','goalIds':ids}
write('P20.current-text-preimage.author.config.json',conf)

ret=D/'retained-current-AM';ret.mkdir(exist_ok=True)
receipt={'artifactKind':'twenty-current-human-AM-exact-retention','selectedWholeGoals':20,'newScientificReviews':0,'newMemoryDecks':0,'retained':[],'activeWrites':0}
for gate,source in [('A','curricula/DE/Gymnasium/quality/semantic-atomicity/canonical-biology-full.review.jsonl'),('M','curricula/DE/Gymnasium/quality/memory-card-review/canonical-biology-full.review.jsonl')]:
    p=ROOT/source;lines=[line for line in p.read_text().splitlines(keepends=True)if json.loads(line)['goalId']in ids];rows=[json.loads(line)for line in lines]
    assert len(rows)==20 and all(r['status']==('atomic'if gate=='A'else'no_memory_needed')for r in rows)
    out=ret/f'{gate}20.exact.rows.jsonl';out.write_text(''.join(lines))
    aconf=read(OLD/f'{gate}20.current.native.config.json');aconf['reviewPath']=str(out.relative_to(ROOT));aconf['scope']={'label':'20 unchanged current human/health goals, retain exact valid A/M decisions without new scientific review','leafGoalIds':ids}
    if gate=='M':
        cards=ROOT/'curricula/DE/Gymnasium/quality/memory-card-review/canonical-biology-full.cards.review.jsonl'
        assert not any(set(json.loads(x)['originGoalIds'])&set(ids)for x in cards.read_text().splitlines())
        cardout=ret/'M20.exact.in-scope.cards.jsonl';cardout.write_text('');aconf['cardReviewPath']=str(cardout.relative_to(ROOT));receipt['inScopeCardRecords']=0
    write(f'{gate}20.current.native.config.json',aconf)
    receipt['retained'].append({'gate':gate,'originalPath':source,'originalSha256':sha(p),'exactRowsPath':str(out.relative_to(ROOT)),'exactRowsSha256':sha(out),'records':20,'status':rows[0]['status'],'newScientificReview':False})
write('current-twenty-retained-AM.exact-binding.author.receipt.json',receipt)
print(json.dumps({'wholeCases':40,'positiveAuthorProfiles':20,'exactRetainedA':20,'exactRetainedM':20,'newMemoryDecks':0,'activeWrites':0}))
